CustomField.formula:
IF(
/*If Account is Country Parent, stores Enterprise_ISR__c value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'),  Enterprise_ISR__c  ,
IF(
/*If Account is Sales site, stores Country Parent Account's Enterprise_ISR__c by traversing one level up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(ParentId))), Parent.Enterprise_ISR__c,Enterprise_ISR__c))
